read='''function read(f){const doc=f.contentDocument,d=doc.querySelector('dialog'),r=d.getBoundingClientRect(),box=e=>{const b=e.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},parts={head:d.querySelector('.dialog-head'),title:d.querySelector('h2'),close:d.querySelector('.dialog-head button'),body:d.querySelector('.dialog-body'),list:d.querySelector('ul'),privacy:d.querySelector('p.small'),footer:d.querySelector('.dialog-footer'),footerClose:d.querySelector('.dialog-footer button')},style=f.contentWindow.getComputedStyle(d);return{id:f.dataset.id,environment:{innerWidth:f.contentWindow.innerWidth,innerHeight:f.contentWindow.innerHeight,clientWidth:doc.documentElement.clientWidth,clientHeight:doc.documentElement.clientHeight,minWidth:f.contentWindow.getComputedStyle(doc.documentElement).minWidth,minHeight:f.contentWindow.getComputedStyle(doc.documentElement).minHeight},x:r.x,y:r.y,width:r.width,height:r.height,parts:Object.fromEntries(Object.entries(parts).map(([k,e])=>[k,box(e)])),texts:{title:parts.title.textContent,close:parts.close.getAttribute('aria-label'),footerClose:parts.footerClose.textContent,privacy:parts.privacy.textContent},bodyScrollHeight:parts.body.scrollHeight,bodyScrollTop:parts.body.scrollTop,dialogScrollHeight:d.scrollHeight,dialogScrollTop:d.scrollTop,shadow:style.boxShadow,palette:{background:style.backgroundColor,border:style.borderColor,radius:style.borderRadius,footer:f.contentWindow.getComputedStyle(parts.footer).backgroundColor},items:[...d.querySelectorAll('li')].map(x=>x.textContent)};}'''
script='const cases='+json.dumps(cases,ensure_ascii=False)+';const frame='+json.dumps(frame,ensure_ascii=False).replace('</','<\\/')+''';const ready=[];for(const c of cases){const f=document.createElement('iframe');f.dataset.id=c.id;f.style.width=c.width+'px';f.style.height=c.height+'px';f.srcdoc=frame.replaceAll('CASE',JSON.stringify(c));ready.push(new Promise(res=>f.onload=async()=>{await f.contentWindow.fixtureReady;res()}));document.getElementById('fixtures').append(f)}'''+read+'''document.getElementById('resultdetails-record').onclick=async()=>{await Promise.all(ready);const rows=[...document.querySelectorAll('iframe')].map(read);const response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows,cases:cases.map((c,i)=>({...c,title:rows[i].texts.title,items:rows[i].items}))})});if(!response.ok)throw Error('Evidence failed');document.getElementById('resultdetails-record').textContent='ResultDetails recorded';};'''
